using System.Net;
using System.Text;
using TrueAuthor.Core;
namespace TrueAuthor.Desktop;
static class LocalDashboard
{
 public const string LiveScript = "let live=true,loading=false;const toggle=document.getElementById('live-toggle');toggle.addEventListener('click',()=>{live=!live;toggle.setAttribute('aria-pressed',String(live));toggle.textContent=live?'Live updates on':'Live updates paused';});setInterval(async()=>{if(!live||loading||document.hidden)return;loading=true;try{const r=await fetch(location.href,{cache:'no-store'});if(!r.ok)throw Error();const next=new DOMParser().parseFromString(await r.text(),'text/html').querySelector('main');const main=document.querySelector('main');if(next&&main.innerHTML!==next.innerHTML){const open=[...main.querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent);const y=scrollY;main.replaceWith(next);for(const d of next.querySelectorAll('details'))if(open.includes(d.querySelector('summary')?.textContent))d.open=true;scrollTo(0,y);}toggle.textContent='Live updates on';}catch{toggle.textContent='App disconnected · retrying';}finally{loading=false;}},3000);";
 public const string Styles = """

*{box-sizing:border-box} :root{color-scheme:light;--ink:#202a36;--muted:#697483;--line:#e5e8ed;--accent:#5446d8}body{margin:0;background:#f8f9fc;color:var(--ink);font:16px/1.6 'Segoe UI',system-ui,sans-serif;-webkit-font-smoothing:antialiased}a{color:var(--accent);text-decoration:none}a:hover{color:#392caf}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid #a99ff5;outline-offset:5px}header{min-height:96px;padding:22px 4.5%;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{display:flex;align-items:center;gap:12px;font-size:22px;font-weight:700;letter-spacing:-.7px;color:var(--ink)}.brand-logo{width:38px;height:38px;object-fit:contain}.brand-mark{display:grid;place-items:center;width:38px;height:42px;background:linear-gradient(145deg,#8145ef,#285aff);color:white;clip-path:polygon(50% 0,96% 17%,90% 66%,72% 86%,50% 100%,28% 86%,10% 66%,4% 17%);font-size:25px;font-weight:700}.brand-divider{height:24px;width:1px;background:var(--line);margin:0 8px}.brand-context{font-size:16px;color:var(--muted);font-weight:400;letter-spacing:0}.header-actions{display:flex;align-items:center;gap:24px}.private-label{color:var(--muted);font-size:15px}.private-label span{margin-right:6px}button,.button-link{font:600 15px/1.3 'Segoe UI',system-ui,sans-serif;cursor:pointer;border:1px solid #dedbf2;border-radius:999px;padding:13px 20px;min-height:46px;background:#f3f1ff;color:#5142bf;display:inline-flex;align-items:center;justify-content:center;gap:12px;transition:background .15s,box-shadow .15s,transform .15s}button:hover,.button-link:hover{background:#eae6ff;box-shadow:0 4px 12px #5344bf12}button:active,.button-link:active{transform:translateY(1px)}#live-toggle::before{content:'';width:7px;height:7px;background:#6e5cdb;border-radius:50%;box-shadow:0 0 0 4px #6e5cdb12}#live-toggle[aria-pressed=false]{background:#f4f5f7;color:#687181;border-color:var(--line)}#live-toggle[aria-pressed=false]::before{background:#98a1af;box-shadow:none}main{max-width:1480px;margin:0 auto;padding:48px 4.5% 32px}.layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:56px}nav{padding-top:8px}.nav-label,.eyebrow{display:block;color:#7b8193;font-size:12px;font-weight:650;letter-spacing:1.8px}.nav-label{padding:0 16px;margin-bottom:20px}nav a{display:block;padding:15px 16px;margin-bottom:8px;border-radius:14px;overflow-wrap:anywhere;color:#626d7c}nav a:hover{background:#f0eefb}nav a.active{background:#eeebfb;color:#5141bd}.nav-title{display:flex;justify-content:space-between;align-items:center;font-weight:600}.count{font-size:13px;border-radius:8px;background:white;padding:0 8px;line-height:25px}nav small{display:block;font-size:13px;margin-top:5px;color:#7c8493}.page-heading{margin:0 0 34px}.page-heading .eyebrow{color:#7263c5;margin:4px 0 17px}h1{font-size:clamp(32px,3.5vw,48px);line-height:1.15;letter-spacing:-1.8px;font-weight:650;margin:12px 0 20px}h2{font-size:24px;line-height:1.35;letter-spacing:-.6px;font-weight:600;margin:0 0 12px}h3{font-size:20px;letter-spacing:-.3px}p{color:var(--muted);line-height:1.75;margin:10px 0 18px}small{color:var(--muted);font-size:14px}section{background:white;border:1px solid var(--line);border-radius:24px;padding:28px;margin-bottom:24px}.empty-state{text-align:center;min-height:350px;padding:42px 28px;background:radial-gradient(ellipse at 50% 0,#f3f0ff 0,white 65%);border-color:#e8e4f5;box-shadow:0 12px 48px #25204403}.document-symbol{color:#7966d7;width:76px;height:76px;display:grid;place-items:center;background:#ece8fb;border-radius:23px;margin:0 auto 22px;transform:rotate(-5deg)}.empty-state .eyebrow{font-size:11px;color:#9288ae;margin-bottom:12px}.empty-state h2{font-size:27px;letter-spacing:-.8px}.empty-state p{font-size:16px;margin:12px auto 24px}.empty-state strong{font-weight:600;color:#505265}.empty-hint{font-size:14px;color:#858399;display:flex;align-items:center;justify-content:center;gap:9px}.hint-dot{width:6px;height:6px;background:#a89ccf;border-radius:50%}.stats{display:flex;gap:36px;flex-wrap:wrap;padding:26px 30px}.stats b{display:block;font-size:30px;font-weight:600;color:var(--ink)}.stats span{font-size:14px;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:20px}.grid section{display:flex;flex-direction:column;margin-bottom:4px}.grid section h2{margin-top:12px}.grid .button-link{align-self:flex-start;margin-top:auto}.pill{display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:999px;padding:10px 16px;margin:4px 6px 8px 0;background:white;font-size:14px;min-height:42px}.pill:hover{border-color:#bcb3ee;background:#f4f1ff}.swatch{display:inline-block;width:12px;height:12px;border-radius:4px;margin-right:8px}.paper{background:white;box-shadow:0 10px 40px #203c3308;border:1px solid var(--line);border-radius:16px;padding:52px;max-width:900px;margin:26px auto;white-space:pre-wrap;overflow-wrap:anywhere;min-height:300px;font:19px/2 Georgia,serif}.paper a{color:inherit}.paper a:hover{outline:2px solid #8271ce}mark{color:inherit;border-radius:3px;padding:2px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:15px/1.8 'Segoe UI',system-ui;background:#f7f8fb;padding:20px;border-radius:14px}summary{cursor:pointer;font-weight:500;padding:14px 0;color:#626c7a;font-size:15px}details{border-top:1px solid var(--line)}details[open]{padding-bottom:14px}.device-details{margin-top:28px}code,dd{overflow-wrap:anywhere}code{font-size:14px}dl{display:grid;grid-template-columns:150px minmax(0,1fr);gap:14px}dt{color:var(--muted)}dd{margin:0}.source:target{outline:2px solid #9484db;outline-offset:4px}footer{margin:24px 0 0;padding:6px 0 0}.privacy-title{font-weight:600;font-size:15px;color:#687286}footer p{font-size:14px;line-height:1.7;margin:6px 0 10px}footer details{border:0}footer summary{padding:0;font-size:14px;color:#8a91a0}footer details p{max-width:720px}@media(max-width:1050px){.layout{grid-template-columns:190px minmax(0,1fr);gap:30px}.brand-context,.brand-divider{display:none}.header-actions{gap:14px}.private-label{font-size:14px}}@media(max-width:700px){header{padding:18px 20px;min-height:80px}.brand{font-size:20px;gap:8px}.brand-mark{width:30px;height:34px;font-size:21px}.private-label{display:none}button{font-size:13px;padding:11px 14px;min-height:42px}main{padding:24px 20px}.layout{grid-template-columns:1fr;gap:24px}nav{display:flex;overflow:auto;gap:8px;align-items:stretch}.nav-label{display:none}nav a{min-width:175px;margin:0}.page-heading{margin-bottom:26px}.page-heading p br,.empty-state p br{display:none}h1{font-size:37px}.empty-state{padding:32px 20px;min-height:330px}.empty-state h2{font-size:24px}.empty-hint{font-size:13px}.paper{padding:24px;font-size:17px}dl{grid-template-columns:1fr;gap:7px}.stats{gap:20px}section{padding:22px;border-radius:20px}}@media(prefers-reduced-motion:reduce){button,.button-link{transition:none}}

""";
 static string E(string? s) => WebUtility.HtmlEncode(s ?? "");
 static string Key(AuditOrigin o) => o.Kind == "paste" ? string.Join('\u001f',o.Kind,o.Source,o.Host,o.LocalUrl) : o.Kind;
 static string Label(AuditOrigin o) => o.Kind switch { "typed" => "Directly typed", "preexisting" => "Already in document", "unobserved" => "Unobserved changes", _ => o.Source == "unknown" ? "Paste · unknown source" : o.Source };
 static readonly string[] Colors = ["#ffe4ad","#dcd5ff","#c7eaff","#ffd6de","#bceee0","#ecd5b9"];
 static string Color(AuditOrigin o,int i) => o.Kind switch { "typed" => "#ddf2e3", "preexisting" => "#e6e9ed", "unobserved" => "#f7ced0", _ => Colors[i % Colors.Length] };
 static string Title(SavedAudit s) => string.IsNullOrWhiteSpace(s.Title) ? "Writing project · " + s.DocumentId.ToString()[..8] : s.Title;
 public static string Render(string basePath,string document,string? directory=null)
 {
  directory ??= AuditLocalStore.DirectoryPath;
  var entries = new List<(SavedAudit saved,DocumentAudit audit,DateTime updated)>(); int unreadable=0;
  foreach(var path in (Directory.Exists(directory)?Directory.GetFiles(directory,"*.taudit"):[]).OrderByDescending(File.GetLastWriteTimeUtc))
   try { var s=AuditLocalStore.Load(path); entries.Add((s,DocumentAudit.Restore(s.Document),File.GetLastWriteTime(path))); }
   catch(Exception error) when(error is System.Security.Cryptography.CryptographicException or System.Text.Json.JsonException or IOException or FormatException or ArgumentException) { unreadable++; }
  var html=new StringBuilder("<!doctype html><html lang='en'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Your documents · True Author</title><style>" + Styles + "</style>");
  html.Append($"<header><a class='brand' href='{E(basePath)}'><img class='brand-logo' src='{Branding.IconData}' alt=''>TrueAuthor<span class='brand-divider'></span><span class='brand-context'>Document library</span></a><div class='header-actions'><span class='private-label'><span aria-hidden='true'>◈</span> Private · on this PC</span><button id='live-toggle' type='button' aria-pressed='true'>Live updates on</button></div></header><main><div class='layout'><nav aria-label='Document library'><span class='nav-label'>WORKSPACE</span><a class='{(document.Length==0?"active":"")}' href='{E(basePath)}'><span class='nav-title'>All documents <span class='count'>{entries.Count}</span></span><small>Your saved writing histories</small></a>");
  foreach(var e in entries) html.Append($"<a class='{(document==e.saved.DocumentId.ToString()?"active":"")}' href='{E(basePath)}?document={e.saved.DocumentId}'>{E(Title(e.saved))}<small>{e.audit.Text.Length:N0} text units · {E(e.updated.ToString("MMM d, HH:mm"))}</small></a>");
  html.Append("</nav><div>");
  var current=entries.Where(e=>e.saved.DocumentId.ToString()==document).ToList();
  if(current.Count==0)
  {
   html.Append("<div class='page-heading'><span class='eyebrow'>YOUR WRITING, IN VIEW</span><h1>Every document.<br>Its story, all here.</h1><p>Your words, edits and sources, together in one private space.<br>Choose a document to explore its writing history.</p></div>");
   if(document.Length>0) html.Append("<section role='alert'>This document was not found. Choose one from the library.</section>");
   if(entries.Count==0) html.Append("<section class='empty-state'><div class='document-symbol' aria-hidden='true'><svg width='38' height='44' viewBox='0 0 38 44' fill='none'><path d='M8 2h15l12 12v25a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3V7a5 5 0 0 1 5-5Z' stroke='currentColor' stroke-width='1.8'/><path d='M22 3v12h12M11 24h16M11 31h11' stroke='currentColor' stroke-width='1.8' stroke-linecap='round'/></svg></div><span class='eyebrow'>A FRESH START</span><h2>Your next document starts here.</h2><p>Open the TrueAuthor desktop app, choose <strong>New project</strong>,<br>and select the document you want to track.</p><div class='empty-hint'><span class='hint-dot'></span>Your writing history will appear here automatically.</div></section>");
   html.Append("<div class='grid'>");
   foreach(var e in entries) html.Append($"<section><small>{E(e.updated.ToString("MMM d, yyyy · HH:mm"))}</small><h2><a href='{E(basePath)}?document={e.saved.DocumentId}'>{E(Title(e.saved))}</a></h2><p>{e.audit.Text.Length:N0} text units · {e.audit.Passages.Count} paste segments · {e.audit.Gaps} gaps</p><pre>{E(e.audit.Text.Length==0?"No document text captured yet.":e.audit.Text[..Math.Min(180,e.audit.Text.Length)])}</pre><a class='button-link' href='{E(basePath)}?document={e.saved.DocumentId}'>Open document <span aria-hidden='true'>↗</span></a></section>");
   html.Append("</div>");
  }
  else Detail(html,current[0].saved,current[0].audit,current[0].updated);
  if(unreadable>0) html.Append($"<p>{unreadable} audits could not be opened. Their files have been kept.</p>");
  html.Append($"<details class='device-details'><summary>Device information</summary><code>{E(DeviceIdentity.InstallationId())}</code><p>No account needed. This ID is an identifier, not an access password.</p></details><footer><span class='privacy-title'>Private by design.</span><p>Your document text and source details stay on this PC. Optional cloud sync sends audit metadata only.</p><details><summary>About this writing history</summary><p>This view shows current saved text and paste history. This adapter does not record full revision snapshots.</p></details></footer></div></div></main></html>");
  html.Append("<script>" + LiveScript + "</script>"); return html.ToString();
 }
 static void ObservationReport(StringBuilder h, SavedAudit saved)
 {
  h.Append($"<section><h2>Capture coverage</h2><p>Latest capture mode: <b>{E(saved.CaptureMode)}</b>. Desktop-only browser text depends on Windows accessibility. Extension-assisted snapshots add document-level mapping; neither mode proves authorship.</p>");
  if (saved.Observations is { } o)
  {
   h.Append($"<p>{o.TypedKeys:N0} typing-key observations · {o.PasteAttempts:N0} paste shortcut observations · {o.UncertainEvents:N0} uncertain input events</p><p>These are desktop observations, not confirmed document insertions. They are not included in the highlighted passage totals or attributed to document positions. This recent observation log remains local.</p>");
   foreach(var input in o.Recent)
   {
    h.Append($"<details><summary>{E(input.At.ToLocalTime().ToString("g"))} · {E(input.Kind)} · {input.Units:N0} clipboard units</summary><p>{E(input.Source?.Name ?? "Unknown source")} · {E(input.Source?.Url)} · {E(input.Source?.Detection ?? "none")}</p>");
    if(input.Text is not null) h.Append($"<pre>{E(input.Text)}</pre>");
    h.Append("</details>");
   }
  }
  h.Append("</section>");
 }
 static void Detail(StringBuilder h,SavedAudit s,DocumentAudit d,DateTime updated)
 {
  var a=d.Activity;var spans=d.Spans();var origins=spans.Select(p=>p.Origin).Concat(d.Passages.Select(p=>p.Origin)).DistinctBy(Key).ToList();
  h.Append($"<small>DOCUMENT AUDIT</small><h1>{E(Title(s))}</h1><p>Saved {E(updated.ToString("g"))} · {d.Text.Length:N0} UTF-16 text units</p><section class='stats'><span><b>{a.TypedInserted:N0}</b>typed units</span><span><b>{a.PasteInserted:N0}</b>pasted units</span><span><b>{d.Deleted:N0}</b>deleted units</span><span><b>{d.Gaps:N0}</b>recording gaps</span></section><a class='pill' href='#preview'>Full document</a><a class='pill' href='#sources'>Sources &amp; paste history</a><a class='pill' href='#details'>Audit details</a><h2 id='preview'>Full document preview</h2><p>Click a highlighted passage to see its source. Colors identify recorded origins, not an AI prediction.</p>");
  for(int i=0;i<origins.Count;i++) h.Append($"<a class='pill' href='#source-{i}'><span class='swatch' style='background:{Color(origins[i],i)}'></span>{E(Label(origins[i]))}</a>");
  h.Append("<article class='paper' aria-label='Full highlighted document'>");
  foreach(var p in spans) {int i=origins.FindIndex(o=>Key(o)==Key(p.Origin));h.Append($"<a id='passage-{p.Start}' href='#source-{i}' aria-label='{E(Label(p.Origin))}, text position {p.Start}'><mark style='background:{Color(p.Origin,i)}' title='{E(Label(p.Origin)+" · "+p.Origin.LocalUrl)}'>{E(d.Text.Substring(p.Start,p.Length))}</mark></a>");}
  if(d.Text.Length==0)h.Append("No document text captured yet. Start recording a selected writing surface in the desktop app.");
  h.Append("</article><h2 id='sources'>Sources &amp; paste history</h2><p>Introduced totals include deleted text. Remaining totals describe the current document. Unknown sources stay unknown.</p>");
  for(int i=0;i<origins.Count;i++)
  {
   var o=origins[i];var matching=spans.Where(p=>Key(p.Origin)==Key(o)).ToList();var pastes=d.Passages.Where(p=>Key(p.Origin)==Key(o)).ToList();int remaining=matching.Sum(p=>p.Length);
   h.Append($"<section class='source' id='source-{i}'><h3><span class='swatch' style='background:{Color(o,i)}'></span>{E(Label(o))}</h3><p>{remaining:N0} remaining units · {(d.Text.Length>0?100.0*remaining/d.Text.Length:0):0.0}% of current document");
   if(o.Kind=="paste") h.Append($" · {pastes.Sum(p=>p.Characters):N0} introduced units · {pastes.Count} paste segments");
   h.Append("</p>");
   if(o.Kind=="paste") h.Append($"<dl><dt>Source location</dt><dd>{E(string.IsNullOrEmpty(o.LocalUrl)?string.IsNullOrEmpty(o.Host)?"No source URL observed":o.Host:o.LocalUrl)}</dd><dt>Evidence</dt><dd>{E(string.Join(", ",matching.Select(p=>p.Origin.Detection).Concat(pastes.Select(p=>p.Origin.Detection)).Distinct()))}</dd><dt>Category</dt><dd>{E(o.Category)}</dd></dl>");
   else h.Append($"<p>{(o.Kind=="typed"?"Correlated typing input. This does not establish the author's identity or exclude manually retyped material.":o.Kind=="preexisting"?"Already present when capture began. Its earlier origin was not observed.":"Changes without enough input or source evidence. No origin is asserted.")}</p>");
   foreach(var p in matching)h.Append($"<a class='pill' href='#passage-{p.Start}'>View passage · {p.Start}–{p.Start+p.Length}</a>");
   foreach(var p in pastes) {int survives=spans.Where(x=>x.Origin.PassageId==p.Id).Sum(x=>x.Length);h.Append($"<details><summary>Paste · {E(p.RecordedAt.ToLocalTime().ToString("g"))} · {p.Characters:N0} introduced · {survives:N0} remaining{(survives==0?" · removed from current text":"")}</summary><p>Capture method: {E(p.Origin.Detection)} · Source: {E(p.Origin.LocalUrl)}</p><pre>{E(p.OriginalText)}</pre></details>");}
   h.Append("</section>");
  }
  ObservationReport(h,s);
  h.Append($"<section id='details'><h2>Audit details</h2><dl><dt>Document ID</dt><dd>{s.DocumentId}</dd><dt>Started</dt><dd>{E(s.StartedAt.ToLocalTime().ToString("g"))}</dd><dt>Capture adapter</dt><dd>{E(s.Adapter)}</dd><dt>Saved state</dt><dd>{(s.Paused?"Paused":"Active")}</dd><dt>Activity history</dt><dd>{(a.Complete?"Counters available from audit start":"Partial historical counters")}</dd><dt>Edit events</dt><dd>{a.EditEvents:N0}</dd><dt>Delete events</dt><dd>{a.DeleteEvents:N0}</dd><dt>Preexisting units</dt><dd>{a.PreexistingInserted:N0}</dd><dt>Unobserved units</dt><dd>{a.UnobservedInserted:N0}</dd><dt>Cloud checkpoints</dt><dd>{s.Sequence}</dd><dt>Queued uploads</dt><dd>{s.Pending.Count}</dd><dt>Text fingerprint</dt><dd><code>{Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(d.Text)))}</code></dd></dl><p>Counts are UTF-16 text units, not words. Gaps and unknown changes remain visible.</p></section>");
 }
}
